"""Plain-language content of the lab: themes, experiments and figure explainers.

Every figure entry has: what the chart shows, how to read it, and what it
tells us. Paths are relative to results/. `section` is the start of the
FINDINGS.md heading whose text is shown as the full write-up.
"""

from __future__ import annotations


def fig(path, title, what, read, tells):
    return {"path": path, "title": title, "what": what, "read": read, "tells": tells}


THEMES = [
    ("foundations", "1. Foundations", "Can a big-picture description have its own law?"),
    ("psi", "2. Testing a popular measure", "Does the information score Ψ detect emergence?"),
    ("closure", "3. Closure and interaction", "Is the flock's law closed, and is it made by interaction?"),
    ("size", "4. Size and universal laws", "Which level has a law that does not depend on system size?"),
    ("share", "5. The interaction share S", "A measure that separates real emergence from averaging"),
    ("animals", "6. Real animals", "Fish, pigeons and zebrafish"),
    ("rules", "7. Finding the interaction rule", "Ruling out explanations across scales"),
    ("layers", "8. Discovering variables and layers", "Letting the data choose what to measure"),
    ("brains", "9. A new layer: neurons and brain areas", "Is a brain area's activity shaped by its neurons interacting?"),
    ("markets", "10. A new domain: markets", "Is market volatility shaped by coordination between industries?"),
    ("unify", "11. One equation across domains", "What do all the interaction-share results have in common?"),
    ("numbers", "12. Beyond nature: prime numbers", "Can memory tell a prime search where to look?"),
    ("extremes", "13. Testing the extremes", "Phase transitions, bad random numbers, any group size, time run backwards"),
]


# ---------------------------------------------------------------- e41–e44 figures

def _elim_figs(n: int, prev: str) -> list[dict]:
    d = f"e{n}_figures/"
    figs = [
        fig(d + "01_scorecard.png", "Scorecard",
            "Each pre-registered prediction of this experiment, with PASS or FAIL.",
            "One row per prediction. Predictions were written down and hashed before the run, so a FAIL is a real failure, not a moved goalpost.",
            "The quickest summary of what worked and what did not."),
        fig(d + "02_funnel.png", "Elimination funnel",
            "How many of the 25 candidate interaction rules survive each stage of the pruned search. Left: synthetic schools where the true rule is known. Right: real fish recordings.",
            "Each line is one school. Read it left to right: start (25 rules) → stage 0 (one test removes a whole family) → stage 1 (short forecasts) → stage 2 (long simulations). The crosses at the far right show how many survive the conventional search that simulates every rule.",
            "Cheap tests remove most explanations before the expensive simulations. A line ending at 0 means that no candidate rule could reproduce the school."),
        fig(d + "03_candidate_map.png", "Where each candidate rule was eliminated",
            "A grid of the 25 candidate rules (rows) against every school (columns): synthetic schools, real schools, and virtual groups of fish that never met.",
            "Colour shows the stage at which a rule was eliminated (red = stage 0, orange = stage 1, yellow = stage 2), light green = survived, dark green = the answer. Black boxes mark the true rule in synthetic schools. Rule names: k6 = 6 nearest neighbours, r10 = everyone within 10 cm; A = alignment, C = attraction, R = repulsion.",
            "For synthetic schools the true rule should survive. For virtual groups the answer should be 'none', because those fish never interacted. Any other answer there is a false alarm."),
        fig(d + "04_family_test.png", "Stage 0: the family test",
            "One statistic per school (z0) that tests whether pairwise interactions change the group's total turn.",
            "Bars above the red dashed line (z0 = 3) eliminate the whole family of symmetric-alignment rules at once. Black-edged bars are synthetic schools whose truth lies outside that family, so they should be above the line.",
            "A theorem (verified in Lean) says symmetric alignment can never change the total turn. One regression can therefore remove four candidate rules together."),
        fig(d + "05_cost.png", "Search cost",
            "Computer time of the pruned search against the conventional search that simulates every candidate.",
            "Lower bars mean cheaper. Labels give pruned/conventional seconds.",
            "Pruning pays off (about 2× faster) when there is something to eliminate, and costs extra when nothing interacts."),
        fig(d + "06_stage2_stats.png", "Stage 2: simulated vs real school",
            "Long simulations of the best surviving rule compared with the recording on five school statistics: polarization, its variability, milling, spread and nearest-neighbour distance.",
            "Black dot = observed, coloured dot = simulated; numbers are observed/simulated. Red marks a statistic outside the tolerance.",
            "Shows whether the model produces a school that looks like the real one. Spread (how tight the school is) is the hardest statistic to match."),
        fig(d + "07_schools.png", "Schools in the tank",
            "The last 30 s of real trajectories (blue) next to a long simulation of the chosen rule (orange) in the 1 m tank.",
            "Lines are paths and arrows are fish at the final moment.",
            "A visual check of whether the simulated school moves and holds together like the real one."),
        fig(d + "08_timeseries.png", "Time series",
            "School statistics over time, real against simulated.",
            "Compare the level and how much each curve fluctuates.",
            "Long-run statistics can match even when moment-to-moment behaviour differs, and this chart shows both."),
        fig(d + f"09_progress_e39_{prev}.png", "Progress across the series",
            "How the key numbers moved from e39 to this experiment as the model was improved.",
            "Each group of bars is one experiment in the series.",
            "Shows which model changes actually helped."),
        fig(d + "10_full_results_text.png", "Full text output",
            "The complete printed results of the run, as an image.",
            "Every number reported in FINDINGS comes from this output.",
            "The raw record, for checking details."),
        fig(d + "11_truth_stage2_check.png", "Stage 2 on the true rule",
            "Stage 2 applied to synthetic schools using their own true rule, which should always pass.",
            "Bars show how far the truth's simulated statistics sit from the data. They should stay inside the allowed band.",
            "A sanity check of the test itself. In e41 the truth failed on tiny mismatches, which revealed that a significance test was the wrong tool. It was replaced by an equivalence margin in e42."),
    ]
    if n >= 42:
        figs.append(fig(d + "12_virtual_gate.png", "The virtual-group gate",
                        "For each real recording: does the matching no-interaction control (time-shifted fish) correctly come out as 'none'? Only then is a rule claimed for the real school.",
                        "Green = yes, red = no. The right-hand column shows the rule claimed, if any.",
                        "A built-in honesty check: if the method finds 'interactions' in fish that never met, nothing it says about real fish can be trusted."))
    if n == 42:
        figs.append(fig(d + "13_cohesion.png", "The cohesion term",
                        "Left: the fitted pull toward the group (positive = fish turn toward it). Right: simulated against observed school spread.",
                        "On the right, points on the diagonal mean the simulation is as tight as the real school.",
                        "Adding a distance-growing pull roughly halved the spread error, so cohesion is real and used."))
    if n >= 43:
        figs.append(fig(d + "14_place_maps.png", "Each fish's own place map",
                        "For each of the 8 fish: the heading it tends to turn toward at each spot in the tank, ignoring the other fish.",
                        "Arrows point where the fish wants to go; longer and yellower = stronger. Most fish circulate around the tank and turn hard at the walls.",
                        "Each fish has its own habits. A model without them would confuse 'all fish like the same places' with 'fish attract each other'."))
    if n == 43:
        figs.append(fig(d + "15_virtual_control_e42_vs_e43.png", "The control, before and after",
                        "How many virtual groups (fish that never met) correctly keep 'none' at each stage, in e42 and e43.",
                        "Higher bars are better; the target is all 8.",
                        "Per-fish place maps did not fix the false alarms, so the place-preference explanation was refuted."))
    if n == 44:
        figs.append(fig(d + "15_virtual_control_e42_to_e44.png", "The control across e42–e44",
                        "How many virtual groups correctly keep 'none' at each stage, in e42, e43 and e44.",
                        "Higher bars are better; the target is all 8.",
                        "e44's heading-aware speed model makes the control behave: 6 of 8 gates open."))
        figs.append(fig(d + "16_mechanism.png", "The mechanism, confirmed",
                        "Left: how much the no-interaction model over-predicts school spread in fish that never met. Right: the fake 'speed up toward the group' coefficient in those fish. Grey = e43 model, blue = e44.",
                        "The green band is the pre-registered target. Blue bars should fall inside it.",
                        "The false alarms came from a speed model that ignored heading (fish slow down when heading into a wall). Fixing that removed the fake attraction."))
    return figs


